import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"CLI Commands","description":"","frontmatter":{},"headers":[],"relativePath":"cli/overview.md","filePath":"cli/overview.md","lastUpdated":1784743339000}'),c={name:"cli/overview.md"};function r(i,e,s,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="cli-commands" tabindex="-1">CLI Commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to &quot;CLI Commands&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <code>swag2mcp</code> CLI is the single entry point for all operations — from initializing a workspace and managing API specifications to starting an MCP server for LLM integration. It provides <strong>13 commands</strong> that cover the full lifecycle of working with OpenAPI/Swagger/Postman specs.</p><h3 id="what-the-cli-solves" tabindex="-1">What the CLI solves <a class="header-anchor" href="#what-the-cli-solves" aria-label="Permalink to &quot;What the CLI solves&quot;">​</a></h3><ul><li><strong>Workspace lifecycle</strong> — create (<code>init</code>), inspect (<code>info</code>, <code>ls</code>), clean (<code>clean</code>), update (<code>update</code>), and remove (<code>delete</code>) workspaces and their contents</li><li><strong>Spec &amp; collection management</strong> — add (<code>add</code>), list (<code>ls</code>), and delete (<code>delete</code>) API specifications and their collections</li><li><strong>Running modes</strong> — start the MCP server for LLM tool access (<code>mcp</code>) or launch the interactive TUI explorer (<code>run</code>)</li><li><strong>Diagnostics</strong> — validate configuration (<code>validate</code>), show version (<code>version</code>), display runtime info (<code>info</code>)</li><li><strong>Backup &amp; restore</strong> — full workspace round-trip via ZIP (<code>export</code>, <code>import</code>)</li></ul><h3 id="key-nuances" tabindex="-1">Key nuances <a class="header-anchor" href="#key-nuances" aria-label="Permalink to &quot;Key nuances&quot;">​</a></h3><ul><li><strong>Path resolution</strong> — commands that accept <code>[path]</code> expect a <strong>workspace directory</strong> (not a file path). Resolution order: explicit <code>[path]</code> → current directory (<code>./</code>) → <code>~/.swag2mcp/</code>. The CLI appends <code>swag2mcp.yaml</code> automatically. Always pass an explicit path when running as a service or in IDE config to avoid loading the wrong workspace.</li><li><strong>Spec vs Collection</strong> — a <strong>spec</strong> represents a logical API service (e.g. &quot;Open-Meteo API&quot;), while a <strong>collection</strong> is one OpenAPI/Swagger/Postman file. A spec can have multiple collections.</li><li><strong><code>--version</code></strong> is supported both as a flag (<code>swag2mcp --version</code>) and as a subcommand (<code>swag2mcp version</code>).</li><li><strong><code>add spec</code> / <code>add collection</code></strong> accept YAML input via <code>--yaml</code> (inline string or <code>-</code> for stdin). Piping from a file or heredoc avoids shell quoting issues with special characters.</li><li><strong><code>delete</code></strong> requires a TTY (interactive terminal). There is no <code>--force</code> or <code>--yes</code> flag — it always prompts for selection and confirmation.</li><li><strong><code>mcp</code></strong> is the primary command for LLM integration. It supports three transports: <code>stdio</code> (default), <code>sse</code>, and <code>streamable-http</code>. The <code>--disable-llm-auth</code> flag (default: <code>true</code>) removes the <code>auth</code> tool from the MCP tool list, preventing the LLM from seeing or requesting tokens. Auth still works — tokens are obtained through the standard config mechanism, not via the LLM. This mode is recommended for <strong>production</strong> (LLM never has access to credentials). For <strong>debugging</strong> or when using short-lived tokens, set <code>--disable-llm-auth=false</code> to let the LLM request fresh tokens via the <code>auth</code> tool.</li><li><strong><code>validate</code></strong> checks YAML syntax, config structure, spec file existence, URL reachability, spec format (OpenAPI/Swagger/Postman), auth settings, and HTTP client correctness. It does <strong>not</strong> test authentication endpoints or API endpoint availability.</li><li><strong><code>export</code> / <code>import</code></strong> provide a full workspace round-trip — config file, spec files, cache, and auth scripts are all included in the ZIP archive.</li><li><strong><code>clean</code></strong> removes <code>cache/</code> and <code>responses/</code> directories but preserves <code>specs/</code> and <code>auth_scripts/</code>. Old responses (&gt;48h) are also cleaned automatically on <code>mcp</code> startup.</li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>Initialize a workspace directory with default config</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>Add a spec or collection to the configuration</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>Delete a spec or collection interactively</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>List all specs and their collections</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>Launch the interactive TUI API explorer</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>Validate configuration and spec files</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>Clear cached specs and invocation responses</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>Re-validate, re-cache, and re-index all specs</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>Start the MCP server for LLM tool access</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>Print the swag2mcp version</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>Show detailed configuration and runtime information</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>Import spec files or restore workspace from ZIP</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>Export workspace as a portable ZIP backup</td></tr></tbody></table><h2 id="global-flags" tabindex="-1">Global Flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global Flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Show version (same as <code>version</code> subcommand)</td></tr><tr><td><code>--help</code></td><td>Show help for any command</td></tr></tbody></table>',11)])])}const m=t(c,[["render",r]]);export{g as __pageData,m as default};
